const baseUrl = readline();
const N = parseInt(readline());

const params = [];
for (let i = 0; i < N; i++) {
    const inputs = readline().split(' ');
    const key = inputs[0];
    const value = inputs[1];
    params.push(`${key}=${value}`);
}

if (N > 0) {
    console.log(`${baseUrl}?${params.join('&')}`);
} else {
    console.log(baseUrl);
}
